tools.example:
BRD:
DISPLAY = 'Preset_Top' None 1 17 18 19 20 21 23 25 39 41 51;
SCH:
Grid Default;
Change Width 0.006in;

ASSIGN C+F 'RUN find.ulp';
BRD:
ASSIGN A+P Set Obstacle_Mode Push;

set palette black;
set palette 0 0xFF000000; # background
set palette 4 0xCCC90D0C; # top, symbols

SET COLOR_LAYER 91 2;
SET FILL_LAYER 1 1;
SET FILL_LAYER 2 3;

Set Fill_Layer Top Empty;
Set Fill_Layer Bottom Empty;
Set Display_Mode NoDrill;

Grid mm 1 off;
Layer Dimension;
Wire 0 (0 0) (160 100) (0 0);
Window Fit;

DISPLAY = _current_layers_ @;
DISPLAY ALL;
RIPUP;
DISPLAY NONE 19;
GROUP (-32 -32) (-32 32) (32 32) (32 -32);
DELETE (>0 0);

LBR:
ASSIGN C+N 'run editnext-dev-sym-pac.ulp;';
ASSIGN C+R 'run cmd-rename-in-lbr.ulp;';

GRID INCH 0.1 2 lines on;
SET AUTO_JUNCTION OFF;
SET WIRE_BEND 2;

OPEN hexapodu.brd
AUTO LOAD hexapodu.ctl;
AUTO;

OPEN singlesided.brd
AUTO LOAD singlesided_v.ctl;
AUTO;
